usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Evals.New(
		context.TODO(),
		openai.EvalNewParams{
			Name: param.NewOpt[string]("string"),
			Metadata: map[string]string{"key": "string"},
			DataSourceConfig: openai.CreateEvalCustomDataSourceConfig{Type: "custom", ItemSchema: map[string]any{"key": nil}, IncludeSampleSchema: false},
			TestingCriteria: []openai.CreateEvalRequestTestingCriteriaItem{openai.CreateEvalLabelModelGrader{Type: "label_model", Name: "string", Model: "string", Input: []openai.CreateEvalItem{openai.CreateEvalItemSimpleInputMessage{Role: "string", Content: "string"}}, Labels: []string{"string"}, PassingLabels: []string{"string"}}},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
